-- ==========================================================
-- POKÉMON SLEEP MASTER: DDL & DATAMINED SEED DATA COMPLETO
-- Ejecuta este script completo en el SQL Editor de Supabase
-- ==========================================================

-- 0. LIMPIEZA PREVIA (Elimina tablas temporales y recrea limpiamente)
DROP TABLE IF EXISTS pokemon_species CASCADE;
DROP TABLE IF EXISTS ingredients CASCADE;
DROP TABLE IF EXISTS recipes CASCADE;
DROP TABLE IF EXISTS subskills CASCADE;
DROP TABLE IF EXISTS natures CASCADE;

-- 1. TABLA: pokemon_species
CREATE TABLE IF NOT EXISTS pokemon_species (
    id TEXT PRIMARY KEY,
    dex_number INT NOT NULL,
    name TEXT NOT NULL,
    specialty TEXT NOT NULL CHECK (specialty IN ('Bayas', 'Ingredientes', 'Habilidades', 'Todo')),
    type TEXT NOT NULL,
    berry_name TEXT NOT NULL,
    base_frequency INT NOT NULL,
    frequency_str TEXT NOT NULL,
    ingredient_rate NUMERIC(5,2) NOT NULL,
    skill_rate NUMERIC(5,2) NOT NULL,
    carry_limit INT NOT NULL,
    friendship_points INT NOT NULL,
    evolution_count INT NOT NULL DEFAULT 0,
    evolution_left INT NOT NULL DEFAULT 0,
    is_fully_evolved BOOLEAN NOT NULL DEFAULT FALSE,
    main_skill TEXT NOT NULL,
    ingredients_config JSONB NOT NULL,
    avatar_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE pokemon_species ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read pokemon_species" ON pokemon_species;
CREATE POLICY "Allow public read pokemon_species" ON pokemon_species FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow anon write pokemon_species" ON pokemon_species;
CREATE POLICY "Allow anon write pokemon_species" ON pokemon_species FOR ALL USING (true);

-- 2. TABLA: ingredients
CREATE TABLE IF NOT EXISTS ingredients (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    base_vigor INT NOT NULL,
    icon_url TEXT,
    aliases TEXT[] DEFAULT '{}'
);
ALTER TABLE ingredients ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read ingredients" ON ingredients;
CREATE POLICY "Allow public read ingredients" ON ingredients FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow anon write ingredients" ON ingredients;
CREATE POLICY "Allow anon write ingredients" ON ingredients FOR ALL USING (true);

-- 3. TABLA: recipes
CREATE TABLE IF NOT EXISTS recipes (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    dish_type TEXT NOT NULL CHECK (dish_type IN ('curry', 'salad', 'dessert')),
    base_vigor INT NOT NULL,
    ingredients_required JSONB NOT NULL,
    description TEXT
);
ALTER TABLE recipes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read recipes" ON recipes;
CREATE POLICY "Allow public read recipes" ON recipes FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow anon write recipes" ON recipes;
CREATE POLICY "Allow anon write recipes" ON recipes FOR ALL USING (true);

-- 4. TABLA: subskills
CREATE TABLE IF NOT EXISTS subskills (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    tier TEXT NOT NULL CHECK (tier IN ('white', 'blue', 'gold')),
    effect_type TEXT NOT NULL,
    effect_value NUMERIC(6,3) NOT NULL,
    description TEXT
);
ALTER TABLE subskills ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read subskills" ON subskills;
CREATE POLICY "Allow public read subskills" ON subskills FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow anon write subskills" ON subskills;
CREATE POLICY "Allow anon write subskills" ON subskills FOR ALL USING (true);

-- 5. TABLA: natures
CREATE TABLE IF NOT EXISTS natures (
    name TEXT PRIMARY KEY,
    up_stat TEXT,
    down_stat TEXT,
    speed_mod NUMERIC(4,2) NOT NULL,
    ing_mod NUMERIC(4,2) NOT NULL,
    skill_mod NUMERIC(4,2) NOT NULL,
    energy_mod NUMERIC(4,2) NOT NULL,
    exp_mod NUMERIC(4,2) NOT NULL
);
ALTER TABLE natures ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read natures" ON natures;
CREATE POLICY "Allow public read natures" ON natures FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow anon write natures" ON natures;
CREATE POLICY "Allow anon write natures" ON natures FOR ALL USING (true);

